-- Forward-only correction for Phase 4 migration 021.
--
-- Migration 021 dropped real_football_teams(league_id, name) uniqueness even
-- though duplicate-name identity applies to players, not real-world clubs. Restore
-- the original key without rewriting the already-published migration. Distinct
-- player_profiles remain independently identified by UUID and may share names.
--
-- If duplicate real-team labels were inserted after 021, stop rather than guessing
-- which row to keep: reconcile references by immutable team ID, then retry.
do $$
declare
  v_constraint pg_catalog.pg_constraint%rowtype;
  v_columns text[];
begin
  select c.* into v_constraint
    from pg_catalog.pg_constraint c
   where c.conrelid = 'public.real_football_teams'::regclass
     and c.conname = 'real_football_teams_league_id_name_key';

  if found then
    select array_agg(a.attname::text order by k.ordinality)
      into v_columns
      from unnest(v_constraint.conkey) with ordinality as k(attnum, ordinality)
      join pg_catalog.pg_attribute a
        on a.attrelid = v_constraint.conrelid and a.attnum = k.attnum;
    if v_constraint.contype <> 'u'
       or v_constraint.condeferrable
       or v_columns is distinct from array['league_id', 'name']::text[] then
      raise exception 'existing real-team name constraint has an unexpected definition; inspect manually';
    end if;
    return;
  end if;

  if exists (
    select 1
      from public.real_football_teams
     group by league_id, name
    having count(*) > 1
  ) then
    raise exception 'cannot restore real-team name uniqueness: duplicate (league_id, name) rows exist; resolve them by ID before retrying';
  end if;

  alter table public.real_football_teams
    add constraint real_football_teams_league_id_name_key unique (league_id, name);
end $$;
